create or replace function public.configure_staff(_staff_id uuid,_primary_branch_id uuid,_landing_route text,_compact_mode boolean,_show_prices boolean,_show_stock boolean,_allow_keyboard_shortcuts boolean,_receipt_auto_print boolean,_sound_feedback boolean,_permissions jsonb default '{}'::jsonb) returns boolean language plpgsql security definer set search_path=public as $func$ declare sid uuid; uid uuid:=auth.uid(); k text; v jsonb; begin select store_id into sid from public.staff_accounts where id=_staff_id; if sid is null or not private.has_store_role(sid,uid,array['owner'::public.store_role,'manager'::public.store_role]) then raise exception 'Not authorized'; end if; if _primary_branch_id is not null and not exists(select 1 from public.branches where id=_primary_branch_id and store_id=sid) then raise exception 'Invalid branch'; end if; update public.staff_accounts set primary_branch_id=_primary_branch_id, updated_at=now() where id=_staff_id;
insert into public.staff_settings(staff_id,store_id,landing_route,compact_mode,show_prices,show_stock,allow_keyboard_shortcuts,receipt_auto_print,sound_feedback) values(_staff_id,sid,coalesce(nullif(_landing_route,''),'/sell'),_compact_mode,_show_prices,_show_stock,_allow_keyboard_shortcuts,_receipt_auto_print,_sound_feedback) on conflict(staff_id) do update set landing_route=excluded.landing_route,compact_mode=excluded.compact_mode,show_prices=excluded.show_prices,show_stock=excluded.show_stock,allow_keyboard_shortcuts=excluded.allow_keyboard_shortcuts,receipt_auto_print=excluded.receipt_auto_print,sound_feedback=excluded.sound_feedback,updated_at=now();
for k,v in select key,value from jsonb_each(coalesce(_permissions,'{}'::jsonb)) loop insert into public.staff_permission_overrides(store_id,staff_id,permission,allowed) values(sid,_staff_id,k,coalesce((v->>0)::boolean,false)) on conflict(staff_id,permission) do update set allowed=excluded.allowed,updated_at=now(); end loop; return true; end $func$;
revoke all on function public.configure_staff(uuid,uuid,text,boolean,boolean,boolean,boolean,boolean,boolean,jsonb) from public; grant execute on function public.configure_staff(uuid,uuid,text,boolean,boolean,boolean,boolean,boolean,boolean,jsonb) to authenticated;
